import numpy as np
p=np.load('source_pixels.npz')['rgb'].astype(float)
# match each frame domino region to static frame0 via shifted patch; search shift dx,dy around expected
def match(fi,box,search=8):
 x1,x2,y1,y2=box; ref=p[0,y1:y2,x1:x2]; best=(1e9,None)
 for dy in range(-search,search+1):
  for dx in range(-search,search+1):
   xa=x1+dx;ya=y1+dy;xb=xa+x2-x1;yb=ya+y2-y1
   if xa<0 or ya<0 or xb>256 or yb>144:continue
   d=np.abs(p[fi,ya:yb,xa:xb]-ref).mean()
   if d<best[0]:best=(d,(dx,dy))
 return best
for box in [(58,84,34,101),(101,116,34,101),(141,153,34,103),(177,195,34,106)]:
